import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Plus, Search, RefreshCw, Power, Settings, Trash2, Edit2, Wifi, WifiOff, Thermometer, Droplets, Wind, Flame, Activity } from 'lucide-react';

interface Device {
  id: string;
  name: string;
  type: 'temperature' | 'humidity' | 'smoke' | 'co' | 'water';
  status: 'online' | 'offline';
  value: number;
  unit: string;
  room: string;
  battery: number;
  lastUpdate: string;
}

const mockDevices: Device[] = [
  { id: '1', name: 'Living Room Temp', type: 'temperature', status: 'online', value: 23.5, unit: '°C', room: 'Living Room', battery: 85, lastUpdate: '2 min ago' },
  { id: '2', name: 'Bedroom Humidity', type: 'humidity', status: 'online', value: 45, unit: '%', room: 'Bedroom', battery: 72, lastUpdate: '5 min ago' },
  { id: '3', name: 'Kitchen Smoke', type: 'smoke', status: 'online', value: 0, unit: 'ppm', room: 'Kitchen', battery: 90, lastUpdate: '1 min ago' },
  { id: '4', name: 'Basement CO', type: 'co', status: 'offline', value: 0, unit: 'ppm', room: 'Basement', battery: 30, lastUpdate: '1 hour ago' },
  { id: '5', name: 'Bathroom Water', type: 'water', status: 'online', value: 0, unit: '', room: 'Bathroom', battery: 65, lastUpdate: '3 min ago' },
];

const typeConfig: Record<string, { icon: typeof Thermometer; color: string; bgColor: string; label: string }> = {
  temperature: { icon: Thermometer, color: 'text-[#ff4757]', bgColor: 'bg-[#ff4757]/10', label: 'temperature' },
  humidity: { icon: Droplets, color: 'text-[#00d4ff]', bgColor: 'bg-[#00d4ff]/10', label: 'humidity' },
  smoke: { icon: Flame, color: 'text-[#ffa502]', bgColor: 'bg-[#ffa502]/10', label: 'smoke' },
  co: { icon: Wind, color: 'text-[#ff6b81]', bgColor: 'bg-[#ff6b81]/10', label: 'co' },
  water: { icon: Activity, color: 'text-[#00ff88]', bgColor: 'bg-[#00ff88]/10', label: 'water' },
};

export function Devices() {
  const { t } = useTranslation('app');
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<string>('all');
  const [filterStatus, setFilterStatus] = useState<string>('all');
  const [devices, setDevices] = useState(mockDevices);
  const [showAddModal, setShowAddModal] = useState(false);

  const filteredDevices = devices.filter(device => {
    const matchesSearch = device.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         device.room.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesType = filterType === 'all' || device.type === filterType;
    const matchesStatus = filterStatus === 'all' || device.status === filterStatus;
    return matchesSearch && matchesType && matchesStatus;
  });

  const handleToggleDevice = (deviceId: string) => {
    setDevices(devices.map(d => 
      d.id === deviceId ? { ...d, status: d.status === 'online' ? 'offline' : 'online' } : d
    ));
  };

  const handleRemoveDevice = (deviceId: string) => {
    if (confirm(t('confirm'))) {
      setDevices(devices.filter(d => d.id !== deviceId));
    }
  };

  const handleAddDevice = () => {
    const newDevice: Device = {
      id: Date.now().toString(),
      name: 'New Device',
      type: 'temperature',
      status: 'offline',
      value: 0,
      unit: '°C',
      room: 'Unknown',
      battery: 100,
      lastUpdate: 'Just now',
    };
    setDevices([...devices, newDevice]);
    setShowAddModal(false);
  };

  const onlineCount = devices.filter(d => d.status === 'online').length;

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-white">{t('deviceManagement')}</h1>
          <p className="text-sm text-[#6b7a9a]">{t('manageSensors')}</p>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={() => setDevices(mockDevices)}
            className="flex items-center gap-2 px-4 py-2 bg-white/5 border border-white/10 rounded-xl text-white hover:bg-white/10 transition-colors"
          >
            <RefreshCw className="w-4 h-4" />
            <span>{t('refresh')}</span>
          </button>
          <button
            onClick={() => setShowAddModal(true)}
            className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-[#00d4ff] to-[#00ff88] text-[#0a1628] font-semibold rounded-xl hover:opacity-90 transition-opacity"
          >
            <Plus className="w-4 h-4" />
            <span>{t('addDevice')}</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-[#0f2137] rounded-2xl p-4 border border-white/5">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-[#00d4ff] to-[#00ff88] flex items-center justify-center">
              <Wifi className="w-5 h-5 text-[#0a1628]" />
            </div>
            <div>
              <p className="text-2xl font-bold text-white">{devices.length}</p>
              <p className="text-sm text-[#6b7a9a]">{t('devices')}</p>
            </div>
          </div>
        </div>
        <div className="bg-[#0f2137] rounded-2xl p-4 border border-white/5">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-[#00ff88]/10 flex items-center justify-center">
              <Wifi className="w-5 h-5 text-[#00ff88]" />
            </div>
            <div>
              <p className="text-2xl font-bold text-white">{onlineCount}</p>
              <p className="text-sm text-[#6b7a9a]">{t('online')}</p>
            </div>
          </div>
        </div>
        <div className="bg-[#0f2137] rounded-2xl p-4 border border-white/5">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-[#ffa502]/10 flex items-center justify-center">
              <WifiOff className="w-5 h-5 text-[#ffa502]" />
            </div>
            <div>
              <p className="text-2xl font-bold text-white">{devices.length - onlineCount}</p>
              <p className="text-sm text-[#6b7a9a]">{t('offline')}</p>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-[#0f2137] rounded-2xl p-4 border border-white/5">
        <div className="flex flex-col md:flex-row items-center gap-4">
          <div className="flex-1 relative w-full">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[#6b7a9a]" />
            <input
              type="text"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder={t('searchPlaceholder')}
              className="w-full pl-12 pr-4 py-3 bg-white/5 border border-white/10 rounded-xl text-white placeholder-[#6b7a9a] focus:outline-none focus:border-[#00d4ff]/50"
            />
          </div>
          <div className="flex items-center gap-4 w-full md:w-auto">
            <select
              value={filterType}
              onChange={(e) => setFilterType(e.target.value)}
              className="w-full md:w-auto px-4 py-3 bg-white/5 border border-white/10 rounded-xl text-white focus:outline-none focus:border-[#00d4ff]/50"
            >
              <option value="all">{t('allTypes')}</option>
              <option value="temperature">{t('temperature')}</option>
              <option value="humidity">{t('humidity')}</option>
              <option value="smoke">{t('smoke')}</option>
              <option value="co">{t('co')}</option>
              <option value="water">{t('water')}</option>
            </select>
            <select
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value)}
              className="w-full md:w-auto px-4 py-3 bg-white/5 border border-white/10 rounded-xl text-white focus:outline-none focus:border-[#00d4ff]/50"
            >
              <option value="all">{t('allStatus')}</option>
              <option value="online">{t('online')}</option>
              <option value="offline">{t('offline')}</option>
            </select>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredDevices.length > 0 ? (
          filteredDevices.map((device) => {
            const config = typeConfig[device.type];
            const Icon = config.icon;
            return (
              <div key={device.id} className="bg-[#0f2137] rounded-2xl p-4 border border-white/5">
                <div className="flex items-start justify-between mb-4">
                  <div className="flex items-center gap-3">
                    <div className={`w-12 h-12 rounded-xl ${config.bgColor} flex items-center justify-center`}>
                      <Icon className={`w-6 h-6 ${config.color}`} />
                    </div>
                    <div>
                      <h3 className="font-medium text-white">{device.name}</h3>
                      <p className="text-sm text-[#6b7a9a]">{device.room}</p>
                    </div>
                  </div>
                  <span className={`text-xs px-2 py-1 rounded-full ${device.status === 'online' ? 'bg-[#00ff88]/10 text-[#00ff88]' : 'bg-[#ffa502]/10 text-[#ffa502]'}`}>
                    {t(device.status)}
                  </span>
                </div>

                <div className="flex items-end justify-between mb-4">
                  <div>
                    <p className="text-3xl font-bold text-white">
                      {device.value}
                      <span className="text-lg text-[#6b7a9a] ml-1">{device.unit}</span>
                    </p>
                    <p className="text-sm text-[#6b7a9a] mt-1">{t(config.label)}</p>
                  </div>
                  <div className="text-right">
                    <div className="flex items-center gap-2">
                      <div className="w-20 h-2 bg-white/10 rounded-full overflow-hidden">
                        <div 
                          className="h-full rounded-full transition-all"
                          style={{ 
                            width: `${device.battery}%`,
                            backgroundColor: device.battery > 50 ? '#00ff88' : device.battery > 20 ? '#ffa502' : '#ff4757'
                          }}
                        />
                      </div>
                      <span className="text-sm text-[#6b7a9a]">{device.battery}%</span>
                    </div>
                    <p className="text-xs text-[#6b7a9a] mt-1">{device.lastUpdate}</p>
                  </div>
                </div>

                <div className="flex items-center justify-between pt-4 border-t border-white/5">
                  <button
                    onClick={() => handleToggleDevice(device.id)}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-lg transition-colors ${
                      device.status === 'online' 
                        ? 'bg-[#ff4757]/10 text-[#ff4757] hover:bg-[#ff4757]/20' 
                        : 'bg-[#00ff88]/10 text-[#00ff88] hover:bg-[#00ff88]/20'
                    }`}
                  >
                    <Power className="w-4 h-4" />
                    <span className="text-sm">{device.status === 'online' ? t('stop') : t('start')}</span>
                  </button>
                  <div className="flex items-center gap-2">
                    <button className="p-2 rounded-lg hover:bg-white/5 transition-colors">
                      <Edit2 className="w-4 h-4 text-[#6b7a9a]" />
                    </button>
                    <button className="p-2 rounded-lg hover:bg-white/5 transition-colors">
                      <Settings className="w-4 h-4 text-[#6b7a9a]" />
                    </button>
                    <button 
                      onClick={() => handleRemoveDevice(device.id)}
                      className="p-2 rounded-lg hover:bg-[#ff4757]/10 transition-colors"
                    >
                      <Trash2 className="w-4 h-4 text-[#ff4757]" />
                    </button>
                  </div>
                </div>
              </div>
            );
          })
        ) : (
          <div className="col-span-full bg-[#0f2137] rounded-2xl p-12 text-center border border-white/5">
            <Activity className="w-16 h-16 text-[#6b7a9a] mx-auto mb-4" />
            <p className="text-white text-lg mb-2">{t('noData')}</p>
            <p className="text-sm text-[#6b7a9a]">{t('adjustFilter')}</p>
          </div>
        )}
      </div>

      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="fixed inset-0 bg-black/50" onClick={() => setShowAddModal(false)} />
          <div className="relative bg-[#0f2137] rounded-2xl p-6 border border-white/10 w-full max-w-md">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-bold text-white">{t('addDevice')}</h3>
              <button onClick={() => setShowAddModal(false)} className="text-[#6b7a9a] hover:text-white">
                <Plus className="w-6 h-6 rotate-45" />
              </button>
            </div>
            <div className="space-y-4">
              <div>
                <label className="block text-sm text-[#6b7a9a] mb-2">{t('name')}</label>
                <input
                  type="text"
                  placeholder={t('enterUsername')}
                  className="w-full px-4 py-3 bg-white/5 border border-white/10 rounded-xl text-white placeholder-[#6b7a9a] focus:outline-none focus:border-[#00d4ff]/50"
                />
              </div>
              <div>
                <label className="block text-sm text-[#6b7a9a] mb-2">{t('type')}</label>
                <select className="w-full px-4 py-3 bg-white/5 border border-white/10 rounded-xl text-white focus:outline-none focus:border-[#00d4ff]/50">
                  <option value="temperature">{t('temperature')}</option>
                  <option value="humidity">{t('humidity')}</option>
                  <option value="smoke">{t('smoke')}</option>
                  <option value="co">{t('co')}</option>
                  <option value="water">{t('water')}</option>
                </select>
              </div>
              <div>
                <label className="block text-sm text-[#6b7a9a] mb-2">{t('room')}</label>
                <input
                  type="text"
                  placeholder="Living Room"
                  className="w-full px-4 py-3 bg-white/5 border border-white/10 rounded-xl text-white placeholder-[#6b7a9a] focus:outline-none focus:border-[#00d4ff]/50"
                />
              </div>
            </div>
            <div className="flex items-center gap-3 mt-6">
              <button onClick={() => setShowAddModal(false)} className="flex-1 px-4 py-3 bg-white/5 border border-white/10 rounded-xl text-white hover:bg-white/10 transition-colors">
                {t('cancel')}
              </button>
              <button onClick={handleAddDevice} className="flex-1 px-4 py-3 bg-gradient-to-r from-[#00d4ff] to-[#00ff88] text-[#0a1628] font-semibold rounded-xl hover:opacity-90 transition-opacity">
                {t('add')}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
