import { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Plus, Trash2, Save } from 'lucide-react';
import { useAppStore } from '../store';
import type { Rule, RuleCondition, RuleAction, SensorType, Operator, RuleActionType } from '../types';

const sensorTypes: SensorType[] = ['SMOKE', 'TEMPERATURE', 'HUMIDITY', 'CO', 'WATER'];
const operators: Operator[] = ['>', '<', '=', '!='];
const actionTypes: RuleActionType[] = ['LOG', 'ALERT', 'WEBHOOK'];

const operatorLabels: Record<Operator, string> = {
  '>': '大于',
  '<': '小于',
  '=': '等于',
  '!=': '不等于',
};

const actionLabels: Record<RuleActionType, string> = {
  LOG: '记录日志',
  ALERT: '发送告警',
  WEBHOOK: '调用Webhook',
};

export function RuleEditor() {
  const { rule_id } = useParams<{ rule_id: string }>();
  const navigate = useNavigate();
  const { rules, createRule, updateRule, fetchRules } = useAppStore();
  const isEdit = !!rule_id;

  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [enabled, setEnabled] = useState(true);
  const [conditions, setConditions] = useState<RuleCondition[]>([
    { sensor_type: undefined, operator: '>', value: 0, window_seconds: undefined },
  ]);
  const [actions, setActions] = useState<RuleAction[]>([{ type: 'LOG', target: undefined, message: undefined }]);
  const [cooldownMinutes, setCooldownMinutes] = useState(5);

  useEffect(() => {
    fetchRules();
  }, [fetchRules]);

  useEffect(() => {
    if (isEdit && rule_id) {
      const rule = rules.find((r) => r.rule_id === rule_id);
      if (rule) {
        setName(rule.name);
        setDescription(rule.description);
        setEnabled(rule.enabled);
        setConditions(rule.conditions.length > 0 ? rule.conditions : [{ sensor_type: undefined, operator: '>', value: 0, window_seconds: undefined }]);
        setActions(rule.actions.length > 0 ? rule.actions : [{ type: 'LOG', target: undefined, message: undefined }]);
        setCooldownMinutes(rule.cooldown_minutes);
      }
    }
  }, [isEdit, rule_id, rules]);

  const handleAddCondition = () => {
    setConditions([...conditions, { sensor_type: undefined, operator: '>', value: 0, window_seconds: undefined }]);
  };

  const handleRemoveCondition = (index: number) => {
    if (conditions.length > 1) {
      setConditions(conditions.filter((_, i) => i !== index));
    }
  };

  const handleUpdateCondition = (index: number, updates: Partial<RuleCondition>) => {
    setConditions(
      conditions.map((c, i) => (i === index ? { ...c, ...updates } : c))
    );
  };

  const handleAddAction = () => {
    setActions([...actions, { type: 'LOG', target: undefined, message: undefined }]);
  };

  const handleRemoveAction = (index: number) => {
    if (actions.length > 1) {
      setActions(actions.filter((_, i) => i !== index));
    }
  };

  const handleUpdateAction = (index: number, updates: Partial<RuleAction>) => {
    setActions(
      actions.map((a, i) => (i === index ? { ...a, ...updates } : a))
    );
  };

  const handleSubmit = async () => {
    const ruleData = {
      name,
      description,
      enabled,
      conditions,
      actions,
      cooldown_minutes: cooldownMinutes,
    };

    if (isEdit && rule_id) {
      await updateRule(rule_id, ruleData);
    } else {
      await createRule(ruleData);
    }

    navigate('/rules');
  };

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <button
          onClick={() => navigate('/rules')}
          className="flex items-center gap-2 text-[#00d4ff] hover:underline"
        >
          <ArrowLeft className="w-5 h-5" />
          返回规则列表
        </button>
        <button
          onClick={handleSubmit}
          className="flex items-center gap-2 px-4 py-2 bg-[#00d4ff] text-[#0a1628] font-medium rounded-xl hover:bg-[#00d4ff]/90 transition-colors"
        >
          <Save className="w-5 h-5" />
          保存规则
        </button>
      </div>

      <h1 className="text-2xl font-bold text-white">
        {isEdit ? '编辑规则' : '创建规则'}
      </h1>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="space-y-6">
          <div className="bg-[#0f2137] rounded-xl p-6 border border-white/5">
            <h2 className="text-lg font-semibold text-white mb-4">基本信息</h2>
            <div className="space-y-4">
              <div>
                <label className="block text-sm text-[#6b7a9a] mb-2">规则名称</label>
                <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="输入规则名称"
                  className="w-full px-4 py-3 bg-white/5 border border-white/10 rounded-xl text-white placeholder-[#6b7a9a] focus:outline-none focus:border-[#00d4ff]/50 transition-colors"
                />
              </div>
              <div>
                <label className="block text-sm text-[#6b7a9a] mb-2">规则描述</label>
                <textarea
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="输入规则描述"
                  rows={3}
                  className="w-full px-4 py-3 bg-white/5 border border-white/10 rounded-xl text-white placeholder-[#6b7a9a] focus:outline-none focus:border-[#00d4ff]/50 transition-colors resize-none"
                />
              </div>
              <div className="flex items-center justify-between">
                <label className="text-sm text-[#6b7a9a]">启用规则</label>
                <button
                  onClick={() => setEnabled(!enabled)}
                  className={`w-12 h-6 rounded-full transition-colors ${
                    enabled ? 'bg-[#00d4ff]' : 'bg-[#6b7a9a]'
                  }`}
                >
                  <div
                    className={`w-5 h-5 bg-white rounded-full transition-transform ${
                      enabled ? 'translate-x-6' : 'translate-x-0.5'
                    }`}
                  />
                </button>
              </div>
              <div>
                <label className="block text-sm text-[#6b7a9a] mb-2">冷却时间（分钟）</label>
                <input
                  type="number"
                  value={cooldownMinutes}
                  onChange={(e) => setCooldownMinutes(parseInt(e.target.value) || 0)}
                  min={0}
                  className="w-full px-4 py-3 bg-white/5 border border-white/10 rounded-xl text-white focus:outline-none focus:border-[#00d4ff]/50 transition-colors"
                />
              </div>
            </div>
          </div>

          <div className="bg-[#0f2137] rounded-xl p-6 border border-white/5">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-white">触发条件</h2>
              <button
                onClick={handleAddCondition}
                className="flex items-center gap-1 text-sm text-[#00d4ff] hover:underline"
              >
                <Plus className="w-4 h-4" />
                添加条件
              </button>
            </div>
            <div className="space-y-4">
              {conditions.map((condition, index) => (
                <div key={index} className="bg-white/5 rounded-lg p-4">
                  <div className="flex items-center justify-between mb-3">
                    <span className="text-sm text-[#6b7a9a]">条件 {index + 1}</span>
                    {conditions.length > 1 && (
                      <button
                        onClick={() => handleRemoveCondition(index)}
                        className="text-sm text-[#ff4757] hover:underline"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                    <div>
                      <label className="block text-xs text-[#6b7a9a] mb-1">传感器类型</label>
                      <select
                        value={condition.sensor_type || ''}
                        onChange={(e) => handleUpdateCondition(index, { sensor_type: e.target.value as SensorType | undefined })}
                        className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-lg text-white focus:outline-none focus:border-[#00d4ff]/50 transition-colors appearance-none cursor-pointer"
                      >
                        <option value="">全部类型</option>
                        {sensorTypes.map((type) => (
                          <option key={type} value={type}>{type}</option>
                        ))}
                      </select>
                    </div>
                    <div>
                      <label className="block text-xs text-[#6b7a9a] mb-1">操作符</label>
                      <select
                        value={condition.operator}
                        onChange={(e) => handleUpdateCondition(index, { operator: e.target.value as Operator })}
                        className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-lg text-white focus:outline-none focus:border-[#00d4ff]/50 transition-colors appearance-none cursor-pointer"
                      >
                        {operators.map((op) => (
                          <option key={op} value={op}>{operatorLabels[op]}</option>
                        ))}
                      </select>
                    </div>
                    <div>
                      <label className="block text-xs text-[#6b7a9a] mb-1">阈值</label>
                      <input
                        type="number"
                        value={condition.value}
                        onChange={(e) => handleUpdateCondition(index, { value: parseFloat(e.target.value) || 0 })}
                        className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-lg text-white focus:outline-none focus:border-[#00d4ff]/50 transition-colors"
                      />
                    </div>
                  </div>
                  <div className="mt-3">
                    <label className="block text-xs text-[#6b7a9a] mb-1">持续时间（秒，可选）</label>
                    <input
                      type="number"
                      value={condition.window_seconds || ''}
                      onChange={(e) => handleUpdateCondition(index, { window_seconds: e.target.value ? parseInt(e.target.value) : undefined })}
                      placeholder="持续触发时间"
                      className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-lg text-white placeholder-[#6b7a9a] focus:outline-none focus:border-[#00d4ff]/50 transition-colors"
                    />
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="bg-[#0f2137] rounded-xl p-6 border border-white/5">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-semibold text-white">执行动作</h2>
            <button
              onClick={handleAddAction}
              className="flex items-center gap-1 text-sm text-[#00d4ff] hover:underline"
            >
              <Plus className="w-4 h-4" />
              添加动作
            </button>
          </div>
          <div className="space-y-4">
            {actions.map((action, index) => (
              <div key={index} className="bg-white/5 rounded-lg p-4">
                <div className="flex items-center justify-between mb-3">
                  <span className="text-sm text-[#6b7a9a]">动作 {index + 1}</span>
                  {actions.length > 1 && (
                    <button
                      onClick={() => handleRemoveAction(index)}
                      className="text-sm text-[#ff4757] hover:underline"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  )}
                </div>
                <div className="space-y-3">
                  <div>
                    <label className="block text-xs text-[#6b7a9a] mb-1">动作类型</label>
                    <select
                      value={action.type}
                      onChange={(e) => handleUpdateAction(index, { type: e.target.value as RuleActionType })}
                      className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-lg text-white focus:outline-none focus:border-[#00d4ff]/50 transition-colors appearance-none cursor-pointer"
                    >
                      {actionTypes.map((type) => (
                        <option key={type} value={type}>{actionLabels[type]}</option>
                      ))}
                    </select>
                  </div>
                  {action.type === 'WEBHOOK' && (
                    <div>
                      <label className="block text-xs text-[#6b7a9a] mb-1">Webhook URL</label>
                      <input
                        type="text"
                        value={action.target || ''}
                        onChange={(e) => handleUpdateAction(index, { target: e.target.value || undefined })}
                        placeholder="输入Webhook地址"
                        className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-lg text-white placeholder-[#6b7a9a] focus:outline-none focus:border-[#00d4ff]/50 transition-colors"
                      />
                    </div>
                  )}
                  {action.type !== 'LOG' && (
                    <div>
                      <label className="block text-xs text-[#6b7a9a] mb-1">消息内容</label>
                      <input
                        type="text"
                        value={action.message || ''}
                        onChange={(e) => handleUpdateAction(index, { message: e.target.value || undefined })}
                        placeholder="输入消息内容"
                        className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-lg text-white placeholder-[#6b7a9a] focus:outline-none focus:border-[#00d4ff]/50 transition-colors"
                      />
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>

          <div className="mt-8 p-4 bg-[#00d4ff]/10 rounded-xl">
            <h3 className="text-sm font-medium text-[#00d4ff] mb-2">规则预览</h3>
            <p className="text-sm text-white">
              当 {conditions.map((c) => `${c.sensor_type || '所有传感器'}值 ${operatorLabels[c.operator]} ${c.value}`).join(' 且 ')}
              {cooldownMinutes > 0 && `，且冷却时间 ${cooldownMinutes} 分钟`}
              时，执行：{actions.map((a) => actionLabels[a.type]).join('、')}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
