import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { User, Shield, Bell, Palette, Globe, LogOut, Edit2, Check, X, AlertCircle } from 'lucide-react';
import { authApi } from '../api/client';

interface ProfileData {
  username: string;
  email: string;
  phone: string;
  bindStatus: boolean;
}

export function Profile() {
  const { t, i18n } = useTranslation('app');
  const [profile, setProfile] = useState<ProfileData>({
    username: 'Admin',
    email: '',
    phone: '',
    bindStatus: false,
  });
  const [loading, setLoading] = useState(false);
  const [editingField, setEditingField] = useState<string | null>(null);
  const [editValue, setEditValue] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    loadProfile();
  }, []);

  const loadProfile = async () => {
    setLoading(true);
    try {
      const response = await authApi.getProfile();
      setProfile(response.data.data);
    } catch {
      setProfile({
        username: 'Admin',
        email: '',
        phone: '',
        bindStatus: localStorage.getItem('heiman_access_token') ? true : false,
      });
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (field: string) => {
    setEditingField(field);
    setEditValue(profile[field as keyof ProfileData]?.toString() || '');
    setError('');
  };

  const handleSave = () => {
    if (!editValue.trim()) {
      setError(t('error'));
      return;
    }
    setProfile(prev => ({
      ...prev,
      [editingField!]: editValue,
    }));
    setEditingField(null);
    setEditValue('');
  };

  const handleHeimanBind = () => {
    window.location.href = '/api/auth/login';
  };

  const handleLogout = () => {
    if (confirm(t('logoutConfirm'))) {
      authApi.logout();
    }
  };

  const menuItems = [
    { icon: Shield, label: t('protection'), value: '24/7' },
    { icon: Bell, label: t('notifications'), value: 'Enabled' },
    { icon: Palette, label: t('theme'), value: i18n.language === 'zh' ? '深色模式' : 'Dark Mode' },
    { icon: Globe, label: t('language'), value: i18n.language === 'zh' ? '中文' : i18n.language === 'ja' ? '日本語' : i18n.language === 'ko' ? '한국어' : 'English' },
  ];

  return (
    <div className="p-6 space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-white">{t('profile')}</h1>
        <p className="text-sm text-[#6b7a9a]">{t('manageHomes')}</p>
      </div>

      <div className="bg-[#0f2137] rounded-2xl p-6 border border-white/5">
        <div className="flex items-center gap-6">
          <div className="w-20 h-20 rounded-2xl bg-gradient-to-br from-[#00d4ff] to-[#00ff88] flex items-center justify-center">
            <User className="w-10 h-10 text-[#0a1628]" />
          </div>
          <div className="flex-1">
            <div className="flex items-center gap-3">
              {editingField === 'username' ? (
                <div className="flex items-center gap-2">
                  <input
                    type="text"
                    value={editValue}
                    onChange={(e) => setEditValue(e.target.value)}
                    className="px-3 py-1.5 bg-white/5 border border-[#00d4ff]/50 rounded-lg text-white focus:outline-none focus:border-[#00d4ff]"
                    autoFocus
                  />
                  <button
                    onClick={handleSave}
                    className="p-1.5 rounded-lg bg-[#00d4ff] text-[#0a1628] hover:opacity-90 transition-opacity"
                  >
                    <Check className="w-4 h-4" />
                  </button>
                  <button
                    onClick={() => setEditingField(null)}
                    className="p-1.5 rounded-lg bg-white/10 text-white hover:bg-white/20 transition-opacity"
                  >
                    <X className="w-4 h-4" />
                  </button>
                </div>
              ) : (
                <div className="flex items-center gap-3">
                  <h2 className="text-xl font-bold text-white">{profile.username}</h2>
                  <button
                    onClick={() => handleEdit('username')}
                    className="p-1.5 rounded-lg hover:bg-white/10 transition-colors"
                  >
                    <Edit2 className="w-4 h-4 text-[#6b7a9a]" />
                  </button>
                </div>
              )}
            </div>
            {error && (
              <p className="text-sm text-[#ff4757] mt-1">{error}</p>
            )}
            <p className="text-sm text-[#6b7a9a] mt-1">
              {profile.bindStatus ? t('accountBinding') : t('bindAccount')}
            </p>
          </div>
        </div>

        {!profile.bindStatus && (
          <div className="mt-6 p-4 bg-[#00d4ff]/10 border border-[#00d4ff]/30 rounded-xl">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-[#00d4ff] to-[#00ff88] flex items-center justify-center">
                  <User className="w-5 h-5 text-[#0a1628]" />
                </div>
                <div>
                  <p className="font-medium text-white">{t('accountBinding')}</p>
                  <p className="text-sm text-[#6b7a9a]">{t('bindAccount')}</p>
                </div>
              </div>
              <button
                onClick={handleHeimanBind}
                className="px-4 py-2 bg-gradient-to-r from-[#00d4ff] to-[#00ff88] text-[#0a1628] font-semibold rounded-xl hover:opacity-90 transition-opacity"
              >
                {t('bindAccount')}
              </button>
            </div>
          </div>
        )}
      </div>

      <div className="bg-[#0f2137] rounded-2xl p-6 border border-white/5">
        <h3 className="text-lg font-semibold text-white mb-4">{t('settings')}</h3>
        <div className="space-y-4">
          {menuItems.map((item, index) => (
            <div
              key={index}
              className="flex items-center justify-between p-4 bg-white/5 rounded-xl hover:bg-white/10 transition-colors"
            >
              <div className="flex items-center gap-3">
                <item.icon className="w-5 h-5 text-[#00d4ff]" />
                <span className="text-white">{item.label}</span>
              </div>
              <span className="text-[#6b7a9a]">{item.value}</span>
            </div>
          ))}
        </div>
      </div>

      <div className="bg-[#0f2137] rounded-2xl p-6 border border-white/5">
        <button
          onClick={handleLogout}
          className="w-full flex items-center justify-center gap-3 p-4 bg-[#ff4757]/10 border border-[#ff4757]/30 rounded-xl text-[#ff4757] hover:bg-[#ff4757]/20 transition-colors"
        >
          <LogOut className="w-5 h-5" />
          <span>{t('logout')}</span>
        </button>
      </div>
    </div>
  );
}
