import axios, { AxiosError, AxiosRequestConfig, AxiosResponse } from 'axios';
import type { SensorData, SensorEvent, Rule, SensorHistoryData } from '../types';

const BASE_URL = import.meta.env.VITE_API_URL || '/api';

export interface ApiError {
  status: number;
  message: string;
  code?: string;
}

export interface ApiResponse<T = unknown> {
  data: T;
  success: boolean;
  message?: string;
  code?: string;
}

const api = axios.create({
  baseURL: BASE_URL,
  timeout: 10000,
  headers: {
    'Content-Type': 'application/json',
  },
});

api.interceptors.request.use((config) => {
  const token = localStorage.getItem('heiman_access_token');
  if (token) {
    config.headers.Authorization = `bearer ${token}`;
  }
  return config;
}, (error) => {
  return Promise.reject(error);
});

api.interceptors.response.use(
  (response: AxiosResponse<ApiResponse>) => response,
  async (error: AxiosError<ApiResponse>) => {
    const originalRequest = error.config as AxiosRequestConfig & { _retry?: boolean };

    if (error.response?.status === 401 && !originalRequest._retry) {
      originalRequest._retry = true;

      try {
        const refreshToken = localStorage.getItem('heiman_refresh_token');
        if (!refreshToken) {
          throw new Error('No refresh token');
        }

        const refreshResponse = await axios.post(`${BASE_URL}/auth/refresh`, {
          refresh_token: refreshToken,
        });

        const newToken = refreshResponse.data.access_token;
        localStorage.setItem('heiman_access_token', newToken);

        if (originalRequest.headers) {
          originalRequest.headers.Authorization = `bearer ${newToken}`;
        }

        return api(originalRequest);
      } catch {
        localStorage.removeItem('heiman_access_token');
        localStorage.removeItem('heiman_refresh_token');
        localStorage.removeItem('heiman_remember_me');
        window.location.href = '/auth/login';
        return Promise.reject(error);
      }
    }

    if (error.response?.status === 403) {
      return Promise.reject({
        status: 403,
        message: 'Permission denied',
      });
    }

    if (error.response?.status === 500) {
      return Promise.reject({
        status: 500,
        message: 'Server error',
      });
    }

    if (error.code === 'ECONNABORTED') {
      return Promise.reject({
        status: 0,
        message: 'Request timed out',
      });
    }

    if (!error.response) {
      return Promise.reject({
        status: 0,
        message: 'Network error',
      });
    }

    return Promise.reject({
      status: error.response.status,
      message: error.response.data?.message || 'Request failed',
      code: error.response.data?.code,
    });
  }
);

export const authApi = {
  login: async (username: string, password: string, rememberMe: boolean) => {
    const response = await api.post<ApiResponse<{ access_token: string; refresh_token: string }>>('/auth/login', {
      username,
      password,
    });
    localStorage.setItem('heiman_access_token', response.data.data.access_token);
    localStorage.setItem('heiman_refresh_token', response.data.data.refresh_token);
    if (rememberMe) {
      localStorage.setItem('heiman_remember_me', 'true');
    } else {
      localStorage.removeItem('heiman_remember_me');
    }
    return response.data;
  },
  logout: () => {
    localStorage.removeItem('heiman_access_token');
    localStorage.removeItem('heiman_refresh_token');
    localStorage.removeItem('heiman_remember_me');
    window.location.href = '/auth/login';
  },
  getToken: () => api.get<ApiResponse<{ access_token: string }>>('/auth/token'),
  refreshToken: async () => {
    const refreshToken = localStorage.getItem('heiman_refresh_token');
    if (!refreshToken) {
      throw new Error('No refresh token');
    }
    const response = await api.post<ApiResponse<{ access_token: string }>>('/auth/refresh', {
      refresh_token: refreshToken,
    });
    localStorage.setItem('heiman_access_token', response.data.data.access_token);
    return response.data;
  },
  getCurrentToken: () => localStorage.getItem('heiman_access_token'),
  setToken: (token: string) => localStorage.setItem('heiman_access_token', token),
  clearToken: () => localStorage.removeItem('heiman_access_token'),
  bindAccount: (code: string) => api.post<ApiResponse>('/auth/bind', { code }),
  getProfile: () => api.get<ApiResponse<{ username: string; email: string; phone: string; bindStatus: boolean }>>('/auth/profile'),
};

