import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Cpu, Settings, Play, Square, Download, Upload, Info, CheckCircle, Clock, AlertCircle } from 'lucide-react';

interface Model {
  id: string;
  name: string;
  version: string;
  type: 'classification' | 'detection' | 'forecast';
  status: 'deployed' | 'not_deployed' | 'training';
  description: string;
  accuracy: number;
  lastDeployed: string;
}

const mockModels: Model[] = [
  { id: '1', name: 'Smoke Detection', version: 'v2.1.0', type: 'detection', status: 'deployed', description: 'AI model for smoke detection using sensor data', accuracy: 98.5, lastDeployed: '2024-01-10' },
  { id: '2', name: 'CO Alert', version: 'v1.5.0', type: 'classification', status: 'deployed', description: 'Carbon monoxide level classification model', accuracy: 96.2, lastDeployed: '2024-01-08' },
  { id: '3', name: 'Temp Forecast', version: 'v3.0.0', type: 'forecast', status: 'training', description: 'Temperature prediction model for next 24 hours', accuracy: 89.8, lastDeployed: '-' },
  { id: '4', name: 'Water Leak', version: 'v1.2.0', type: 'detection', status: 'not_deployed', description: 'Water leak detection model', accuracy: 94.7, lastDeployed: '-' },
];

const typeLabels: Record<string, string> = {
  classification: 'classification',
  detection: 'detection',
  forecast: 'forecast',
};

const typeColors: Record<string, string> = {
  classification: 'bg-[#00d4ff]/10 text-[#00d4ff]',
  detection: 'bg-[#00ff88]/10 text-[#00ff88]',
  forecast: 'bg-[#ffa502]/10 text-[#ffa502]',
};

const statusConfig: Record<string, { icon: typeof CheckCircle; color: string; bgColor: string; label: string }> = {
  deployed: { icon: CheckCircle, color: 'text-[#00ff88]', bgColor: 'bg-[#00ff88]/10', label: 'modelDeployed' },
  not_deployed: { icon: Clock, color: 'text-[#ffa502]', bgColor: 'bg-[#ffa502]/10', label: 'modelNotDeployed' },
  training: { icon: AlertCircle, color: 'text-[#00d4ff]', bgColor: 'bg-[#00d4ff]/10', label: 'modelTraining' },
};

export function Models() {
  const { t } = useTranslation('app');
  const [models, setModels] = useState(mockModels);
  const [selectedModel, setSelectedModel] = useState<Model | null>(null);
  const [showConfigModal, setShowConfigModal] = useState(false);

  const handleDeploy = (modelId: string) => {
    setModels(models.map(m => 
      m.id === modelId ? { ...m, status: 'deployed', lastDeployed: new Date().toISOString().split('T')[0] } : m
    ));
  };

  const handleStop = (modelId: string) => {
    setModels(models.map(m => 
      m.id === modelId ? { ...m, status: 'not_deployed' } : m
    ));
  };

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-white">{t('modelManagement')}</h1>
          <p className="text-sm text-[#6b7a9a]">{t('selectModel')}</p>
        </div>
        <div className="flex items-center gap-3">
          <button className="flex items-center gap-2 px-4 py-2 bg-white/5 border border-white/10 rounded-xl text-white hover:bg-white/10 transition-colors">
            <Upload className="w-4 h-4" />
            <span>{t('import')}</span>
          </button>
          <button className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-[#00d4ff] to-[#00ff88] text-[#0a1628] font-semibold rounded-xl hover:opacity-90 transition-opacity">
            <Download className="w-4 h-4" />
            <span>{t('export')}</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-1">
          <div className="bg-[#0f2137] rounded-2xl p-4 border border-white/5">
            <h2 className="text-lg font-semibold text-white mb-4">{t('models')}</h2>
            <div className="space-y-2">
              {models.map((model) => {
                const status = statusConfig[model.status];
                const StatusIcon = status.icon;
                return (
                  <button
                    key={model.id}
                    onClick={() => setSelectedModel(model)}
                    className={`w-full text-left p-4 rounded-xl transition-all ${
                      selectedModel?.id === model.id
                        ? 'bg-[#00d4ff]/10 border border-[#00d4ff]/30'
                        : 'hover:bg-white/5 border border-transparent'
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-[#00d4ff] to-[#00ff88] flex items-center justify-center">
                        <Cpu className="w-5 h-5 text-[#0a1628]" />
                      </div>
                      <div className="flex-1">
                        <p className="font-medium text-white">{model.name}</p>
                        <p className="text-sm text-[#6b7a9a]">{model.version}</p>
                      </div>
                      <StatusIcon className={`w-5 h-5 ${status.color}`} />
                    </div>
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        <div className="lg:col-span-2">
          {selectedModel ? (
            <div className="space-y-6">
              <div className="bg-[#0f2137] rounded-2xl p-6 border border-white/5">
                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-4">
                    <div className="w-14 h-14 rounded-xl bg-gradient-to-br from-[#00d4ff] to-[#00ff88] flex items-center justify-center">
                      <Cpu className="w-7 h-7 text-[#0a1628]" />
                    </div>
                    <div>
                      <h2 className="text-xl font-bold text-white">{selectedModel.name}</h2>
                      <div className="flex items-center gap-3 mt-1">
                        <span className={`text-xs px-2 py-0.5 rounded-full ${typeColors[selectedModel.type]}`}>
                          {t(typeLabels[selectedModel.type])}
                        </span>
                        <span className={`text-xs px-2 py-0.5 rounded-full ${statusConfig[selectedModel.status].bgColor} ${statusConfig[selectedModel.status].color}`}>
                          {t(statusConfig[selectedModel.status].label)}
                        </span>
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => setShowConfigModal(true)}
                      className="p-2 rounded-lg hover:bg-white/5 transition-colors"
                    >
                      <Settings className="w-5 h-5 text-[#6b7a9a]" />
                    </button>
                  </div>
                </div>

                <div className="mt-6">
                  <p className="text-sm text-[#6b7a9a] mb-2">{t('modelDescription')}</p>
                  <p className="text-white">{selectedModel.description}</p>
                </div>

                <div className="grid grid-cols-3 gap-4 mt-6">
                  <div className="bg-white/5 rounded-xl p-4 text-center">
                    <p className="text-2xl font-bold text-white">{selectedModel.accuracy}%</p>
                    <p className="text-sm text-[#6b7a9a]">{t('accuracy')}</p>
                  </div>
                  <div className="bg-white/5 rounded-xl p-4 text-center">
                    <p className="text-2xl font-bold text-white">{selectedModel.version}</p>
                    <p className="text-sm text-[#6b7a9a]">{t('modelVersion')}</p>
                  </div>
                  <div className="bg-white/5 rounded-xl p-4 text-center">
                    <p className="text-2xl font-bold text-white">{selectedModel.lastDeployed}</p>
                    <p className="text-sm text-[#6b7a9a]">{t('lastUpdate')}</p>
                  </div>
                </div>
              </div>

              <div className="bg-[#0f2137] rounded-2xl p-6 border border-white/5">
                <h3 className="text-lg font-semibold text-white mb-4">{t('action')}</h3>
                <div className="flex items-center gap-4">
                  {selectedModel.status === 'deployed' ? (
                    <button
                      onClick={() => handleStop(selectedModel.id)}
                      className="flex items-center gap-2 px-6 py-3 bg-[#ff4757]/10 border border-[#ff4757]/30 rounded-xl text-[#ff4757] hover:bg-[#ff4757]/20 transition-colors"
                    >
                      <Square className="w-5 h-5" />
                      <span>{t('stop')}</span>
                    </button>
                  ) : selectedModel.status === 'training' ? (
                    <button
                      disabled
                      className="flex items-center gap-2 px-6 py-3 bg-white/5 border border-white/10 rounded-xl text-[#6b7a9a] cursor-not-allowed"
                    >
                      <Clock className="w-5 h-5 animate-spin" />
                      <span>{t('modelTraining')}</span>
                    </button>
                  ) : (
                    <button
                      onClick={() => handleDeploy(selectedModel.id)}
                      className="flex items-center gap-2 px-6 py-3 bg-gradient-to-r from-[#00d4ff] to-[#00ff88] text-[#0a1628] font-semibold rounded-xl hover:opacity-90 transition-opacity"
                    >
                      <Play className="w-5 h-5" />
                      <span>{t('deployModel')}</span>
                    </button>
                  )}
                  <button
                    onClick={() => setShowConfigModal(true)}
                    className="flex items-center gap-2 px-6 py-3 bg-white/5 border border-white/10 rounded-xl text-white hover:bg-white/10 transition-colors"
                  >
                    <Settings className="w-5 h-5" />
                    <span>{t('configureParameters')}</span>
                  </button>
                </div>
              </div>

              <div className="bg-[#0f2137] rounded-2xl p-6 border border-white/5">
                <h3 className="text-lg font-semibold text-white mb-4">{t('parameters')}</h3>
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <span className="text-[#6b7a9a]">Sensitivity</span>
                    <span className="text-white">High</span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-[#6b7a9a]">Confidence Threshold</span>
                    <span className="text-white">0.85</span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-[#6b7a9a]">Update Interval</span>
                    <span className="text-white">30s</span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-[#6b7a9a]">Batch Size</span>
                    <span className="text-white">16</span>
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="bg-[#0f2137] rounded-2xl p-12 text-center border border-white/5">
              <Cpu className="w-16 h-16 text-[#6b7a9a] mx-auto mb-4" />
              <p className="text-white text-lg mb-2">{t('selectModel')}</p>
              <p className="text-sm text-[#6b7a9a]">{t('selectHomeHint')}</p>
            </div>
          )}
        </div>
      </div>

      {showConfigModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="fixed inset-0 bg-black/50" onClick={() => setShowConfigModal(false)} />
          <div className="relative bg-[#0f2137] rounded-2xl p-6 border border-white/10 w-full max-w-md">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-bold text-white">{t('configureParameters')}</h3>
              <button onClick={() => setShowConfigModal(false)} className="text-[#6b7a9a] hover:text-white">
                <Info className="w-6 h-6" />
              </button>
            </div>
            <div className="space-y-4">
              <div>
                <label className="block text-sm text-[#6b7a9a] mb-2">Sensitivity</label>
                <select className="w-full px-4 py-3 bg-white/5 border border-white/10 rounded-xl text-white focus:outline-none focus:border-[#00d4ff]/50">
                  <option>Low</option>
                  <option>Medium</option>
                  <option>High</option>
                </select>
              </div>
              <div>
                <label className="block text-sm text-[#6b7a9a] mb-2">Confidence Threshold</label>
                <input type="range" min="0.1" max="0.99" step="0.01" defaultValue="0.85" className="w-full" />
              </div>
              <div>
                <label className="block text-sm text-[#6b7a9a] mb-2">Update Interval (seconds)</label>
                <input type="number" defaultValue="30" className="w-full px-4 py-3 bg-white/5 border border-white/10 rounded-xl text-white focus:outline-none focus:border-[#00d4ff]/50" />
              </div>
            </div>
            <div className="flex items-center gap-3 mt-6">
              <button onClick={() => setShowConfigModal(false)} className="flex-1 px-4 py-3 bg-white/5 border border-white/10 rounded-xl text-white hover:bg-white/10 transition-colors">
                {t('cancel')}
              </button>
              <button onClick={() => setShowConfigModal(false)} className="flex-1 px-4 py-3 bg-gradient-to-r from-[#00d4ff] to-[#00ff88] text-[#0a1628] font-semibold rounded-xl hover:opacity-90 transition-opacity">
                {t('save')}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
