import { useTranslation } from 'react-i18next';
import { Flame, Thermometer, Droplets, Wind, AlertTriangle, Wifi, WifiOff } from 'lucide-react';
import type { SensorData } from '../types';

interface SensorCardProps {
  sensor: SensorData;
  onClick?: () => void;
}

const sensorIcons = {
  SMOKE: Flame,
  TEMPERATURE: Thermometer,
  HUMIDITY: Droplets,
  CO: Wind,
  WATER: Droplets,
};

const statusColors = {
  NORMAL: {
    dot: 'bg-[#00ff88]',
    text: 'text-[#00ff88]',
    bg: 'bg-[#00ff88]/10',
    pulse: '',
  },
  WARNING: {
    dot: 'bg-[#ffa502]',
    text: 'text-[#ffa502]',
    bg: 'bg-[#ffa502]/10',
    pulse: 'animate-pulse',
  },
  ALARM: {
    dot: 'bg-[#ff4757]',
    text: 'text-[#ff4757]',
    bg: 'bg-[#ff4757]/10',
    pulse: 'animate-pulse',
  },
  OFFLINE: {
    dot: 'bg-[#6b7a9a]',
    text: 'text-[#6b7a9a]',
    bg: 'bg-[#6b7a9a]/10',
    pulse: '',
  },
};

export function SensorCard({ sensor, onClick }: SensorCardProps) {
  const { t, i18n } = useTranslation('app');
  const Icon = sensorIcons[sensor.sensor_type];
  const status = statusColors[sensor.status];
  const isOnline = sensor.status !== 'OFFLINE';

  return (
    <div
      className={`bg-[#0f2137] rounded-2xl p-5 border border-white/5 cursor-pointer transition-all duration-300 hover:border-[#00d4ff]/30 hover:shadow-lg hover:shadow-[#00d4ff]/10 hover:scale-[1.02] ${
        sensor.status === 'ALARM' ? 'ring-2 ring-[#ff4757]/50' : ''
      }`}
      onClick={onClick}
    >
      <div className="flex items-start justify-between mb-4">
        <div className={`${status.bg} w-12 h-12 rounded-xl flex items-center justify-center`}>
          <Icon className={`w-6 h-6 ${status.text}`} />
        </div>
        <div className="flex items-center gap-2">
          {isOnline ? (
            <Wifi className="w-4 h-4 text-[#00ff88]" />
          ) : (
            <WifiOff className="w-4 h-4 text-[#6b7a9a]" />
          )}
          <span className={`text-xs font-medium ${status.text}`}>{t(`statusLabels.${sensor.status}`)}</span>
          <div className={`w-2 h-2 rounded-full ${status.dot} ${status.pulse}`} />
        </div>
      </div>

      <h3 className="text-lg font-semibold text-white mb-1">{t(`sensorLabels.${sensor.sensor_type}`)}</h3>
      <p className="text-sm text-[#6b7a9a] mb-4">{sensor.did}</p>

      <div className="flex items-end justify-between">
        <div>
          <p className={`text-2xl font-bold ${status.text}`}>
            {sensor.value}
            <span className="text-sm font-normal text-[#6b7a9a] ml-1">{sensor.unit}</span>
          </p>
        </div>
        {sensor.status === 'ALARM' && (
          <AlertTriangle className="w-6 h-6 text-[#ff4757] animate-bounce" />
        )}
      </div>

      <p className="text-xs text-[#4a5568] mt-3">
        {t('updateTime')} {new Date(sensor.timestamp).toLocaleTimeString(i18n.language)}
      </p>
    </div>
  );
}
