import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate, useLocation, useSearchParams } from 'react-router-dom';
import { Eye, EyeOff, Lock, User, AlertCircle, Loader2, ExternalLink } from 'lucide-react';
import { authApi } from '../api/client';

interface LoginFormData {
  username: string;
  password: string;
  rememberMe: boolean;
}

export function Login() {
  const { t } = useTranslation('app');
  const navigate = useNavigate();
  const location = useLocation();
  const [searchParams] = useSearchParams();
  const [formData, setFormData] = useState<LoginFormData>({
    username: '',
    password: '',
    rememberMe: localStorage.getItem('heiman_remember_me') === 'true',
  });
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    const code = searchParams.get('code');
    const state = searchParams.get('state');
    
    if (code && state) {
      setLoading(true);
      fetch(`/api/auth/heiman_redirect?code=${code}&state=${state}`)
        .then(res => res.json())
        .then(data => {
          if (data.access_token) {
            localStorage.setItem('heiman_access_token', data.access_token);
            localStorage.setItem('heiman_refresh_token', data.refresh_token || '');
            const redirectPath = (location.state as { from?: string })?.from || '/';
            navigate(redirectPath);
          } else {
            setError(t('loginFailed'));
          }
        })
        .catch(() => {
          setError(t('loginFailed'));
        })
        .finally(() => {
          setLoading(false);
        });
    }
  }, [searchParams, navigate, location.state, t]);

  useEffect(() => {
    if (localStorage.getItem('heiman_access_token')) {
      const redirectPath = (location.state as { from?: string })?.from || '/';
      navigate(redirectPath);
    }
  }, [navigate, location.state]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      await authApi.login(formData.username, formData.password, formData.rememberMe);
      const redirectPath = (location.state as { from?: string })?.from || '/';
      navigate(redirectPath);
    } catch (err) {
      setError(t('loginFailed'));
    } finally {
      setLoading(false);
    }
  };

  const handleHeimanBind = () => {
    window.location.href = '/api/auth/login';
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#060d17] via-[#0a1628] to-[#0f2137] flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-[#00d4ff] to-[#00ff88] flex items-center justify-center mx-auto mb-4">
            <Lock className="w-8 h-8 text-[#0a1628]" />
          </div>
          <h1 className="text-3xl font-bold text-white mb-2">{t('login')}</h1>
          <p className="text-[#6b7a9a]">{t('welcomeBack')}</p>
        </div>

        <div className="bg-[#0f2137]/80 backdrop-blur-lg rounded-2xl p-6 border border-white/10 shadow-xl">
          {error && (
            <div className="flex items-center gap-2 px-4 py-3 bg-[#ff4757]/10 border border-[#ff4757]/30 rounded-xl mb-4">
              <AlertCircle className="w-5 h-5 text-[#ff4757]" />
              <span className="text-sm text-[#ff4757]">{error}</span>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-white mb-2">
                {t('username')}
              </label>
              <div className="relative">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[#6b7a9a]" />
                <input
                  type="text"
                  value={formData.username}
                  onChange={(e) => setFormData({ ...formData, username: e.target.value })}
                  className="w-full pl-12 pr-4 py-3 bg-white/5 border border-white/10 rounded-xl text-white placeholder-[#6b7a9a] focus:outline-none focus:border-[#00d4ff]/50 transition-colors"
                  placeholder={t('enterUsername')}
                  required
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-white mb-2">
                {t('password')}
              </label>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[#6b7a9a]" />
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={formData.password}
                  onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                  className="w-full pl-12 pr-12 py-3 bg-white/5 border border-white/10 rounded-xl text-white placeholder-[#6b7a9a] focus:outline-none focus:border-[#00d4ff]/50 transition-colors"
                  placeholder={t('enterPassword')}
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-4 top-1/2 -translate-y-1/2 text-[#6b7a9a] hover:text-white transition-colors"
                >
                  {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                </button>
              </div>
            </div>

            <div className="flex items-center justify-between">
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={formData.rememberMe}
                  onChange={(e) => setFormData({ ...formData, rememberMe: e.target.checked })}
                  className="w-4 h-4 rounded border-white/20 bg-white/5 text-[#00d4ff] focus:ring-[#00d4ff]/50"
                />
                <span className="text-sm text-[#6b7a9a]">{t('rememberMe')}</span>
              </label>
              <button
                type="button"
                className="text-sm text-[#00d4ff] hover:text-[#00ff88] transition-colors"
              >
                {t('forgotPassword')}
              </button>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full py-3 bg-gradient-to-r from-[#00d4ff] to-[#00ff88] text-[#0a1628] font-semibold rounded-xl hover:opacity-90 transition-opacity disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
            >
              {loading ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  <span>{t('loading')}</span>
                </>
              ) : (
                <span>{t('login')}</span>
              )}
            </button>
          </form>

          <div className="mt-6">
            <div className="relative">
              <div className="absolute inset-0 flex items-center">
                <div className="w-full border-t border-white/10" />
              </div>
              <div className="relative flex justify-center text-sm">
                <span className="px-4 bg-[#0f2137] text-[#6b7a9a]">{t('or')}</span>
              </div>
            </div>

            <button
              type="button"
              onClick={handleHeimanBind}
              className="w-full mt-4 py-3 bg-white/5 border border-white/10 rounded-xl text-white hover:bg-white/10 transition-colors flex items-center justify-center gap-2"
            >
              <div className="w-5 h-5 rounded-full bg-gradient-to-br from-[#00d4ff] to-[#00ff88] flex items-center justify-center">
                <span className="text-xs font-bold">H</span>
              </div>
              <span>{t('bindAccount')}</span>
              <ExternalLink className="w-4 h-4" />
            </button>
          </div>
        </div>

        <p className="text-center text-sm text-[#6b7a9a] mt-6">
          {t('noAccount')}
          <button
            type="button"
            className="ml-1 text-[#00d4ff] hover:text-[#00ff88] transition-colors"
          >
            {t('signUp')}
          </button>
        </p>
      </div>
    </div>
  );
}
