import { useState } from "react";
import { useTranslation } from "react-i18next";
import {
  LayoutDashboard,
  Thermometer,
  AlertTriangle,
  Settings,
  Flame,
  Wind,
  Menu,
  X,
  Sun,
  Moon,
  Home,
  FileText,
  Cpu,
  LogOut,
  User,
  Activity,
} from "lucide-react";
import { NavLink, useNavigate } from "react-router-dom";
import { LanguageSwitcher } from "./LanguageSwitcher";
import { useTheme } from "../hooks/useTheme";
import { authApi } from "../api/client";

export type TabKey = "dashboard" | "sensors" | "events" | "rules" | "homes" | "logs" | "models" | "devices" | "profile";

const navItems: { icon: typeof LayoutDashboard; path: string; labelKey: string; tabKey: TabKey }[] = [
  { icon: LayoutDashboard, path: "/", labelKey: "dashboard", tabKey: "dashboard" },
  { icon: Home, path: "/homes", labelKey: "homeManagement", tabKey: "homes" },
  { icon: Activity, path: "/devices", labelKey: "deviceManagement", tabKey: "devices" },
  { icon: Thermometer, path: "/sensors", labelKey: "sensors", tabKey: "sensors" },
  { icon: AlertTriangle, path: "/events", labelKey: "events", tabKey: "events" },
  { icon: FileText, path: "/logs", labelKey: "logs", tabKey: "logs" },
  { icon: Cpu, path: "/models", labelKey: "models", tabKey: "models" },
  { icon: Settings, path: "/rules", labelKey: "rules", tabKey: "rules" },
  { icon: User, path: "/profile", labelKey: "profile", tabKey: "profile" },
];

export function Sidebar() {
  const { t } = useTranslation("app");
  const { effective, toggle } = useTheme();
  const [mobileOpen, setMobileOpen] = useState(false);
  const navigate = useNavigate();

  return (
    <>
      <aside
        className={`fixed inset-y-0 left-0 z-50 w-64 bg-[#0a1628] border-r border-[#1e3a5f] flex flex-col transition-transform duration-300 md:translate-x-0 ${
          mobileOpen ? "translate-x-0" : "-translate-x-full"
        }`}
      >
        <div className="flex items-center justify-between p-4 border-b border-[#1e3a5f]">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-[#00d4ff] to-[#00ff88] flex items-center justify-center">
              <Flame className="w-6 h-6 text-[#0a1628]" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-white">Heiman Agent</h1>
              <p className="text-xs text-[#6b7a9a]">{t("home")}</p>
            </div>
          </div>
          <button
            type="button"
            onClick={() => setMobileOpen(false)}
            className="md:hidden p-2 rounded-lg hover:bg-white/10 transition-colors"
          >
            <X className="w-6 h-6 text-white" />
          </button>
        </div>

        <nav className="flex-1 p-4">
          <ul className="space-y-2">
            {navItems.map((item) => (
              <li key={item.path}>
                <NavLink
                  to={item.path}
                  onClick={() => setMobileOpen(false)}
                  className={({ isActive }) =>
                    `flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-300 ${
                      isActive
                        ? "bg-[#00d4ff]/10 text-[#00d4ff] shadow-lg shadow-[#00d4ff]/20"
                        : "text-[#6b7a9a] hover:text-white hover:bg-white/5"
                    }`
                  }
                >
                  <item.icon className="w-5 h-5" />
                  <span className="font-medium">{t(item.labelKey)}</span>
                </NavLink>
              </li>
            ))}
          </ul>
        </nav>

        <div className="p-4 border-t border-[#1e3a5f] space-y-4">
          <div className="flex items-center justify-between">
            <LanguageSwitcher />
            <div className="relative">
              <button
                type="button"
                onClick={toggle}
                className="inline-flex items-center justify-center rounded-md p-2 text-[#6b7a9a] hover:bg-white/10 hover:text-white transition-colors"
                aria-label={t(effective === "dark" ? "theme.toLight" : "theme.toDark")}
              >
                {effective === "dark" ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
              </button>
            </div>
          </div>
          <div className="flex items-center gap-3 p-3 rounded-xl bg-white/5">
            <div className="w-10 h-10 rounded-full bg-gradient-to-br from-[#00ff88] to-[#00d4ff] flex items-center justify-center">
              <Wind className="w-5 h-5 text-[#0a1628]" />
            </div>
            <div className="flex-1">
              <p className="text-sm font-medium text-white">Admin</p>
              <p className="text-xs text-[#6b7a9a]">{t("online")}</p>
            </div>
            <div className="w-2 h-2 rounded-full bg-[#00ff88] animate-pulse" />
          </div>
          <button
            type="button"
            onClick={() => {
              if (confirm(t("logoutConfirm"))) {
                authApi.logout();
              }
            }}
            className="w-full flex items-center justify-center gap-2 p-3 rounded-xl text-[#6b7a9a] hover:text-[#ff4757] hover:bg-[#ff4757]/10 transition-colors"
          >
            <LogOut className="w-5 h-5" />
            <span>{t("logout")}</span>
          </button>
        </div>
      </aside>

      {mobileOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/50 md:hidden"
          onClick={() => setMobileOpen(false)}
        />
      )}

      <button
        type="button"
        onClick={() => setMobileOpen(true)}
        className="fixed top-4 left-4 z-40 p-2 rounded-lg bg-[#0a1628] border border-[#1e3a5f] text-white md:hidden"
      >
        <Menu className="w-6 h-6" />
      </button>
    </>
  );
}

export function MobileTabBar() {
  const { t } = useTranslation("app");

  return (
    <nav className="fixed bottom-0 left-0 right-0 z-40 bg-[#0a1628] border-t border-[#1e3a5f] md:hidden">
      <div className="flex items-center justify-around p-2">
        {navItems.map((item) => (
          <NavLink
            key={item.path}
            to={item.path}
            className={({ isActive }) =>
              `flex flex-col items-center gap-1 px-4 py-2 rounded-xl transition-all duration-300 ${
                isActive
                  ? "text-[#00d4ff]"
                  : "text-[#6b7a9a]"
              }`
            }
          >
            <item.icon className="w-5 h-5" />
            <span className="text-xs">{t(item.labelKey)}</span>
          </NavLink>
        ))}
      </div>
    </nav>
  );
}
