import { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Flame, Thermometer, Droplets, Wind, AlertTriangle, Wifi, WifiOff } from 'lucide-react';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, Filler } from 'chart.js';
import { sensorApi } from '../api/client';
import type { SensorData, SensorHistoryData } from '../types';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, Filler);

const sensorIcons = {
  SMOKE: Flame,
  TEMPERATURE: Thermometer,
  HUMIDITY: Droplets,
  CO: Wind,
  WATER: Droplets,
};

const sensorLabels: Record<string, string> = {
  SMOKE: '烟雾传感器',
  TEMPERATURE: '温度传感器',
  HUMIDITY: '湿度传感器',
  CO: '一氧化碳传感器',
  WATER: '水浸传感器',
};

const statusClasses = {
  NORMAL: {
    dot: 'bg-[#00ff88]',
    text: 'text-[#00ff88]',
    bg: 'bg-[#00ff88]/10',
    label: '正常',
  },
  WARNING: {
    dot: 'bg-[#ffa502]',
    text: 'text-[#ffa502]',
    bg: 'bg-[#ffa502]/10',
    label: '警告',
  },
  ALARM: {
    dot: 'bg-[#ff4757]',
    text: 'text-[#ff4757]',
    bg: 'bg-[#ff4757]/10',
    label: '告警',
  },
  OFFLINE: {
    dot: 'bg-[#6b7a9a]',
    text: 'text-[#6b7a9a]',
    bg: 'bg-[#6b7a9a]/10',
    label: '离线',
  },
};

export function SensorDetail() {
  const { did } = useParams<{ did: string }>();
  const navigate = useNavigate();
  const [sensor, setSensor] = useState<SensorData | null>(null);
  const [history, setHistory] = useState<SensorHistoryData[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!did) return;

    const fetchData = async () => {
      setLoading(true);
      try {
        const [sensorRes, historyRes] = await Promise.all([
          sensorApi.getById(did),
          sensorApi.getHistory(did, { limit: 24 }),
        ]);
        setSensor(sensorRes.data.data);
        setHistory(historyRes.data.data);
      } catch {
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [did]);

  if (loading) {
    return (
      <div className="p-6">
        <button
          onClick={() => navigate('/sensors')}
          className="flex items-center gap-2 text-[#00d4ff] mb-6"
        >
          <ArrowLeft className="w-5 h-5" />
          返回传感器列表
        </button>
        <div className="bg-[#0f2137] rounded-2xl p-8 border border-white/5 animate-pulse" />
      </div>
    );
  }

  if (!sensor) {
    return (
      <div className="p-6">
        <button
          onClick={() => navigate('/sensors')}
          className="flex items-center gap-2 text-[#00d4ff] mb-6"
        >
          <ArrowLeft className="w-5 h-5" />
          返回传感器列表
        </button>
        <div className="bg-[#0f2137] rounded-2xl p-12 text-center border border-white/5">
          <AlertTriangle className="w-12 h-12 text-[#6b7a9a] mx-auto mb-4" />
          <p className="text-white">传感器不存在</p>
        </div>
      </div>
    );
  }

  const Icon = sensorIcons[sensor.sensor_type];
  const status = statusClasses[sensor.status as keyof typeof statusClasses];
  const isOnline = sensor.status !== 'OFFLINE';

  const chartData = {
    labels: history.map((h) => new Date(h.timestamp).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })),
    datasets: [
      {
        label: `数值 (${sensor.unit})`,
        data: history.map((h) => h.value),
        borderColor: '#00d4ff',
        backgroundColor: 'rgba(0, 212, 255, 0.1)',
        fill: true,
        tension: 0.4,
        pointRadius: 4,
        pointBackgroundColor: '#00d4ff',
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    plugins: {
      legend: {
        display: false,
      },
    },
    scales: {
      x: {
        grid: {
          color: 'rgba(255, 255, 255, 0.05)',
        },
        ticks: {
          color: '#6b7a9a',
        },
      },
      y: {
        grid: {
          color: 'rgba(255, 255, 255, 0.05)',
        },
        ticks: {
          color: '#6b7a9a',
        },
      },
    },
  };

  return (
    <div className="p-6 space-y-6">
      <button
        onClick={() => navigate('/sensors')}
        className="flex items-center gap-2 text-[#00d4ff] hover:underline"
      >
        <ArrowLeft className="w-5 h-5" />
        返回传感器列表
      </button>

      <div className="bg-[#0f2137] rounded-2xl p-6 border border-white/5">
        <div className="flex items-start justify-between mb-6">
          <div className="flex items-center gap-4">
            <div className={`${status.bg} w-16 h-16 rounded-2xl flex items-center justify-center`}>
              <Icon className={`w-8 h-8 ${status.text}`} />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-white">{sensorLabels[sensor.sensor_type]}</h1>
              <p className="text-sm text-[#6b7a9a] mt-1">设备ID: {sensor.did}</p>
            </div>
          </div>
          <div className="flex items-center gap-3">
            {isOnline ? (
              <Wifi className="w-6 h-6 text-[#00ff88]" />
            ) : (
              <WifiOff className="w-6 h-6 text-[#6b7a9a]" />
            )}
            <span className={`text-sm font-medium ${status.text}`}>{status.label}</span>
            <div className={`w-3 h-3 rounded-full ${status.dot} ${sensor.status === 'ALARM' || sensor.status === 'WARNING' ? 'animate-pulse' : ''}`} />
          </div>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <div className="bg-white/5 rounded-xl p-4">
            <p className="text-xs text-[#6b7a9a] mb-1">当前值</p>
            <p className={`text-2xl font-bold ${status.text}`}>
              {sensor.value}
              <span className="text-sm font-normal text-[#6b7a9a] ml-1">{sensor.unit}</span>
            </p>
          </div>
          <div className="bg-white/5 rounded-xl p-4">
            <p className="text-xs text-[#6b7a9a] mb-1">传感器类型</p>
            <p className="text-lg font-semibold text-white">{sensorLabels[sensor.sensor_type]}</p>
          </div>
          <div className="bg-white/5 rounded-xl p-4">
            <p className="text-xs text-[#6b7a9a] mb-1">设备状态</p>
            <p className={`text-lg font-semibold ${status.text}`}>{status.label}</p>
          </div>
          <div className="bg-white/5 rounded-xl p-4">
            <p className="text-xs text-[#6b7a9a] mb-1">更新时间</p>
            <p className="text-lg font-semibold text-white">
              {new Date(sensor.timestamp).toLocaleString('zh-CN')}
            </p>
          </div>
        </div>
      </div>

      <div className="bg-[#0f2137] rounded-2xl p-6 border border-white/5">
        <h2 className="text-lg font-semibold text-white mb-4">历史趋势</h2>
        {history.length === 0 ? (
          <div className="text-center py-12">
            <p className="text-[#6b7a9a]">暂无历史数据</p>
          </div>
        ) : (
          <div className="h-64">
            <Line data={chartData} options={chartOptions} />
          </div>
        )}
      </div>
    </div>
  );
}
