import { create } from 'zustand';
import type { SensorData, SensorEvent, Rule } from '../types';
import { sensorApi, eventApi, ruleApi } from '../api/client';

interface AppState {
  sensors: SensorData[];
  events: SensorEvent[];
  rules: Rule[];
  loading: {
    sensors: boolean;
    events: boolean;
    rules: boolean;
  };
  fetchSensors: () => Promise<void>;
  fetchEvents: () => Promise<void>;
  fetchRules: () => Promise<void>;
  acknowledgeEvent: (eventId: string) => Promise<void>;
  createRule: (data: Omit<Rule, 'rule_id' | 'created_at' | 'updated_at'>) => Promise<void>;
  updateRule: (ruleId: string, data: Partial<Rule>) => Promise<void>;
  deleteRule: (ruleId: string) => Promise<void>;
}

export const useAppStore = create<AppState>((set) => ({
  sensors: [],
  events: [],
  rules: [],
  loading: {
    sensors: false,
    events: false,
    rules: false,
  },
  fetchSensors: async () => {
    set({ loading: { ...useAppStore.getState().loading, sensors: true } });
    try {
      const response = await sensorApi.getAll();
      set({ sensors: response.data.data, loading: { ...useAppStore.getState().loading, sensors: false } });
    } catch {
      set({ loading: { ...useAppStore.getState().loading, sensors: false } });
    }
  },
  fetchEvents: async () => {
    set({ loading: { ...useAppStore.getState().loading, events: true } });
    try {
      const response = await eventApi.getAll();
      set({ events: response.data.data, loading: { ...useAppStore.getState().loading, events: false } });
    } catch {
      set({ loading: { ...useAppStore.getState().loading, events: false } });
    }
  },
  fetchRules: async () => {
    set({ loading: { ...useAppStore.getState().loading, rules: true } });
    try {
      const response = await ruleApi.getAll();
      set({ rules: response.data.data, loading: { ...useAppStore.getState().loading, rules: false } });
    } catch {
      set({ loading: { ...useAppStore.getState().loading, rules: false } });
    }
  },
  acknowledgeEvent: async (eventId) => {
    try {
      await eventApi.acknowledge(eventId);
      set({
        events: useAppStore
          .getState()
          .events.map((event) =>
            event.event_id === eventId ? { ...event, acknowledged: true } : event
          ),
      });
    } catch {}
  },
  createRule: async (data) => {
    try {
      const response = await ruleApi.create(data);
      set({ rules: [...useAppStore.getState().rules, response.data.data] });
    } catch {}
  },
  updateRule: async (ruleId, data) => {
    try {
      const response = await ruleApi.update(ruleId, data);
      set({
        rules: useAppStore
          .getState()
          .rules.map((rule) => (rule.rule_id === ruleId ? response.data.data : rule)),
      });
    } catch {}
  },
  deleteRule: async (ruleId) => {
    try {
      await ruleApi.delete(ruleId);
      set({ rules: useAppStore.getState().rules.filter((rule) => rule.rule_id !== ruleId) });
    } catch {}
  },
}));
